#version 330
#extension GL_ARB_separate_shader_objects : require

// Full-screen triangle for post passes, shipped with the pack (vanilla renamed its own in 26.4).
layout(location = 0) out vec2 texCoord;

void main() {
    vec2 uv = vec2((gl_VertexIndex << 1) & 2, gl_VertexIndex & 2);
    gl_Position = vec4(uv * 2.0 - 1.0, 0.0, 1.0);
    texCoord = uv;
}

#version 330
#extension GL_ARB_separate_shader_objects : require

#include <minecraft:globals.glsl>

uniform sampler2D MainSampler;
uniform sampler2D FontSampler;

#include <coordinates:text.glsl>

layout(location = 0) in vec2 texCoord;
layout(location = 0) out vec4 fragColor;

// The block the player stands in, "x, y, z", in the top-left corner: white with the game's text shadow,
// 2 GUI pixels from the corner, at the GUI scale the game picks with "Auto".
void main() {
    ivec2 pixel = ivec2(texCoord * ScreenSize);
    fragColor = vec4(texelFetch(MainSampler, pixel, 0).rgb, 1.0);

    int scale = autoGuiScale();
    ivec2 topLeft = ivec2(2 * scale, int(ScreenSize.y) - 1 - 2 * scale);
    if (pixel.y > topLeft.y || pixel.y <= topLeft.y - 9 * scale || pixel.x < topLeft.x) {
        return;   // not on the line's rows: don't build it
    }
    vec4 text = drawLine(coordinatesLine(), pixel, topLeft, scale);
    fragColor.rgb = mix(fragColor.rgb, text.rgb, text.a);
}
